traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?dev ;
         rdfs:label ?label .
  ?dev a net:NetworkDevice ;
       rdfs:label "Edge Firewall FW1" .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?triggeredAt
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?triggeredAt .
}
ORDER BY ?triggeredAt
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER(?time > "2026-06-02T14:01:00"^^xsd:dateTime)
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseAlarm ?type ?severity ?device
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm net:alarmType ?type ;
         net:hasSeverity ?severity ;
         net:affectsDevice ?device .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?alarm .
  }
  BIND(?alarm AS ?rootCauseAlarm)
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?root ?rootLabel WHERE {
  ?root (net:causallyLinkedTo)+ net:Alarm_WebTimeout .
  FILTER NOT EXISTS { ?x net:causallyLinkedTo ?root }
  OPTIONAL { ?root rdfs:label ?rootLabel }
}

PREFIX net: <http://example.org/network#>

SELECT ?causeAlarm ?causeLabel WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?causeAlarm .
  ?causeAlarm rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_CPU> (net:causallyLinkedTo)+ <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_Latency> net:causallyLinkedTo+ <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?prev net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  ?cause net:causallyLinkedTo ?effect .
  FILTER(?cause = net:Alarm_Latency && ?effect = net:Alarm_PacketDrop ||
         ?cause = net:Alarm_PacketDrop && ?effect = net:Alarm_Latency)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?label
WHERE {
  ?alarm net:correlatedWith net:Alarm_PacketDrop ;
         rdfs:label ?label .
  FILTER NOT EXISTS { ?alarm net:causallyLinkedTo net:Alarm_PacketDrop }
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>

SELECT ?device WHERE {
  ?incident a net:Incident ;
            net:composedOf ?alarm .
  ?alarm net:affectsDevice ?device .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?alarm .
  }
  FILTER NOT EXISTS {
    ?otherAlarm net:affectsDevice ?otherDevice .
    FILTER(?otherAlarm != ?alarm)
    FILTER NOT EXISTS {
      ?alarm (net:causallyLinkedTo)+ ?otherAlarm .
    }
  }
}
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?avoidedAlarm
WHERE {
  <http://example.org/network#Alarm_CPU> net:causallyLinkedTo ?avoidedAlarm .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?downstream) AS ?preventedAlarms) WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo+ ?downstream .
  FILTER(?downstream != net:Alarm_PacketDrop)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?label
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm rdfs:label ?label .
  FILTER(?alarm != net:Alarm_CPU)
  FILTER NOT EXISTS { net:Alarm_CPU net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?downstreamAlarm .
  FILTER(?downstreamAlarm = net:Alarm_WebTimeout)
}
